float map(vec3 p) {
    float a = iTime+(sin(iTime*.3)*3.);
    p.xy *= mat2(cos(a), -sin(a), sin(a), cos(a));
    p.yz *= mat2(cos(a), -sin(a), sin(a), cos(a));
    p.xz *= mat2(cos(a), sin(a), -sin(a), cos(a));

    //p.xy += 0.5*sin(p.z+iTime);
    //p.zx -= 0.5*cos(p.y+iTime);

    //float sp = length(p - vec3(0,0,0)) - .65;
    float bo = max(abs(p).x-.8, max(abs(p).y-.8, abs(p).z-.8));
    //float to = length(vec2(length(p.xz)-0.8, p.y)) - 0.8;

    return bo; //max(-to,sp);//bo; //min(sp,bo);
}

vec3 palette(float t){
    return 0.35 + 0.5*cos(6.2831*(vec3(0.3,0.5,0.7)*t + vec3(0,0.2,0.4) * sin(iTime * .2)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0,0,-5.0);
    vec3 rd = normalize(vec3(uv, 1.5));
    vec3 col = vec3(0.0);

    float dis;

    float t = 0.0;
    for(float i=0.;i<64.;i++){
        vec3 p = ro + rd * t; 
        float d = map(p); 
        if(d < 0.001) break; t += d * 0.7; col += palette(t*0.1) / (d+0.5);

    }

    fragColor = vec4(col/(10.0+col),1.0);
    //fragColor = vec4(pow(col, vec3(-100000)),1.0); // gamma
}
